/* ── Telefon och stående surfplatta: ≤ 899 px, axeln ligger i vänsterkanten ─── */
@media (max-width: 899px) {
  .hero-logo { right: auto; left: calc(var(--axis) + 14px); top: 22px; width: 34px; }
  .hero-lede { top: auto; left: calc(var(--axis) + 14px); right: var(--gutter); bottom: calc(15svh + 236px); max-width: none; }
  .hero-h { top: 21svh; font-size: clamp(40px, 12.4vw, 104px); }
  .hero-h .r1 { position: static; padding-left: calc(var(--axis) + 0.2em); }
  .hero-h .r2, .hero-h .r3 { padding-left: calc(var(--axis) + 0.2em); }
  .hero-services { left: calc(var(--axis) + 14px); grid-template-columns: minmax(0, 1fr); gap: 12px; bottom: calc(76px + 2svh); }
  .hero-services li { padding-top: 8px; }
  .hero-services p { margin-top: 2px; font-size: 15px; }
  .t-head .r1, .t-head .r2 { padding-left: calc(var(--axis) + 0.2em); }
  .t-type { left: calc(var(--axis) + 0.35em); }
  .p-head { top: 9svh; }
  .p-head .r1, .p-head .r2 { padding-left: calc(var(--axis) + 0.2em); }
  .p-track-wrap { top: 38svh; }
  .p-track { padding-left: calc(var(--axis) + 22px); gap: 36px; }
  .step { width: 76vw; }
  .decisions { grid-template-columns: minmax(0, 1fr); gap: 40px; }
  .decision:nth-child(2) { margin-top: 0; }
  .frame { aspect-ratio: 4 / 5; }
  .k-head { top: 16svh; }
  .k-head .r1, .k-head .r2 { padding-left: calc(var(--axis) + 0.2em); }
  .k-lede { left: calc(var(--axis) + 22px); }
  .lrow { grid-template-columns: minmax(0, 1fr); }
  .lname { text-align: left; padding: 26px var(--gutter) 0 calc(var(--axis) + 22px); }
  .ldesc { padding: 12px var(--gutter) 30px calc(var(--axis) + 22px); }
  .lrow.price-note .lname { display: none; }
  .c-head .r1, .c-head .r2 { padding-left: calc(var(--axis) + 0.2em); }
  .c-body { margin-left: calc(var(--axis) + 22px); }
  .c-mail a { font-size: clamp(20px, 6.4vw, 28px); }
}
@media (hover: none) {
  .use span { opacity: 1; transform: none; }
}
</style>
<noscript><style>html.js .rv, html.js [data-hide] { opacity: 1 !important; transform: none !important; visibility: visible !important; } .frame { clip-path: none !important; } .hero-sel, .p-flood, .narrow { display: none; }</style></noscript>
</head>
