/* HERO: rubrik förskjuten på en hårlinjeaxel, NOT en centrerad hero med knapp */
.hero .stage { background: var(--paper); }
.hero-sel { position: absolute; inset: 0; background: var(--select); clip-path: inset(0% 100% 0% 0%); z-index: 0; }
.hero-axis {
  position: absolute; top: 0; bottom: 0; left: var(--axis); width: var(--caret);
  background: var(--ink); z-index: 3;
}
.hero-logo { position: absolute; top: 30px; right: calc(100% - var(--axis) + 22px); z-index: 2; display: block; width: 40px; color: var(--ink); }
.hero-logo svg { display: block; width: 100%; height: auto; }
.hero-lede { position: absolute; top: 32px; left: calc(var(--axis) + 22px); max-width: 27ch; z-index: 2; font-size: var(--body); line-height: 1.35; }
.hero-h { position: absolute; left: 0; right: 0; top: 31svh; z-index: 2; font-size: var(--d-xl); }
.hero-h .row { white-space: nowrap; }
.hero-h .r1 { position: absolute; right: calc(100% - var(--axis) + 0.16em); top: 0; }
.hero-h .r2 { padding-left: calc(var(--axis) + 0.14em); }
.hero-h .r3 { padding-left: calc(var(--axis) + 0.14em); }
.hero-services {
  position: absolute; left: calc(var(--axis) + 22px); right: var(--gutter); bottom: 15svh; z-index: 2;
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 28px;
  list-style: none; margin: 0; padding: 0;
}
.hero-services li { border-top: 1px solid var(--rule); padding-top: 12px; }
.hero-services h2 { font-weight: 500; font-size: var(--body); display: flex; gap: 0.6em; }
.hero-services h2 span { font-variant-numeric: tabular-nums; color: var(--graphite); font-weight: 400; }
.hero-services p { margin-top: 6px; max-width: 30ch; line-height: 1.4; }

/* ── Akt 2 · Tesen: scrollen skriver ─────────────────────────────────────────── */
/* THESIS: meningen skrivs av scrollen, NOT en ord-för-ord-fade */
.thesis { position: relative; z-index: 2; }

